-- Read-only live preflight for the hand-reviewed v3.13 ledger.
with decision_document as (
  select convert_from(decode(concat(
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  ''
), 'base64'), 'UTF8')::jsonb as payload
),
decisions as (
  select
    (item->>'resource_entity_id')::uuid as resource_entity_id,
    item->>'state' as jurisdiction_state,
    item->>'resource_name' as resource_name,
    item->>'disposition' as disposition,
    nullif(item->'reviewed_address', 'null'::jsonb) as reviewed_address,
    (item->>'map_eligible')::boolean as map_eligible,
    array(
      select value::uuid
      from jsonb_array_elements_text(item->'malformed_location_ids')
    ) as malformed_location_ids
  from decision_document,
  lateral jsonb_array_elements(payload->'decisions') item
),
decision_ids as (
  select d.resource_entity_id, malformed_location_id
  from decisions d
  cross join lateral unnest(d.malformed_location_ids)
    malformed(malformed_location_id)
),
expected_sources as (
  select
    (item->>'location_id')::uuid as location_id,
    (item->>'resource_entity_id')::uuid as resource_entity_id,
    item->>'address_line1' as address_line1,
    item->>'source_pk' as source_pk
  from jsonb_array_elements(convert_from(decode(concat(
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  ''
), 'base64'), 'UTF8')::jsonb) item
),
checks as (
  select jsonb_build_object(
    'decision_payload_sha256', 'b6682ea0eac5a7152145dbbdbe9b766c5ef5475821b199fdf4cc7d777dd19af9',
    'source_snapshot_sha256', '5b85db821027b7b967737dd15d24150546d217385782d31c05bf4ea8e1966d6e',
    'decision_count', (select count(*) from decisions),
    'unique_resource_count', (
      select count(distinct resource_entity_id) from decisions
    ),
    'malformed_id_count', (select count(*) from decision_ids),
    'unique_malformed_id_count', (
      select count(distinct malformed_location_id) from decision_ids
    ),
    'expected_source_count', (select count(*) from expected_sources),
    'map_eligible_count', (
      select count(*) from decisions where map_eligible
    ),
    'addressed_count', (
      select count(*) from decisions where reviewed_address is not null
    ),
    'dispositions', (
      select jsonb_object_agg(disposition, row_count)
      from (
        select disposition, count(*) as row_count
        from decisions
        group by disposition
      ) grouped
    ),
    'missing_entities', (
      select count(*)
      from decisions d
      left join public.luminari_resource_entities e
        on e.resource_entity_id = d.resource_entity_id
      where e.resource_entity_id is null
    ),
    'entity_lineage_drift', (
      select count(*)
      from decisions d
      join public.luminari_resource_entities e
        on e.resource_entity_id = d.resource_entity_id
      where e.state is distinct from d.jurisdiction_state
         or e.source_table is distinct from 'state_directory_logical_record'
    ),
    'review_label_drift', (
      select count(*)
      from decisions d
      join public.luminari_resource_entities e
        on e.resource_entity_id = d.resource_entity_id
      where e.resource_name is distinct from d.resource_name
    ),
    'missing_source_locations', (
      select count(*)
      from expected_sources x
      left join public.luminari_resource_locations l
        on l.location_id = x.location_id
      where l.location_id is null
    ),
    'source_location_drift', (
      select count(*)
      from expected_sources x
      join public.luminari_resource_locations l
        on l.location_id = x.location_id
      where l.resource_entity_id is distinct from x.resource_entity_id
         or l.address_line1 is distinct from x.address_line1
         or l.source_pk is distinct from x.source_pk
         or l.source_table is distinct from 'state_directory_logical_record'
    ),
    'source_location_coordinate_drift', (
      select count(*)
      from expected_sources x
      join public.luminari_resource_locations l
        on l.location_id = x.location_id
      where l.latitude is not null or l.longitude is not null
    ),
    'decision_source_id_set_drift', (
      select
        (select count(*) from (
          select malformed_location_id as location_id from decision_ids
          except
          select location_id from expected_sources
        ) a)
        +
        (select count(*) from (
          select location_id from expected_sources
          except
          select malformed_location_id as location_id from decision_ids
        ) b)
    ),
    'decision_source_owner_drift', (
      select count(*)
      from decision_ids d
      join expected_sources x
        on x.location_id = d.malformed_location_id
      where x.resource_entity_id is distinct from d.resource_entity_id
    )
  ) as result
)
select
  result || jsonb_build_object(
    'dry_run_pass',
      result->>'decision_count' = '446'
      and result->>'unique_resource_count' = '446'
      and result->>'malformed_id_count' = '448'
      and result->>'unique_malformed_id_count' = '448'
      and result->>'expected_source_count' = '448'
      and result->>'map_eligible_count' = '110'
      and result->>'addressed_count' = '209'
      and result->>'missing_entities' = '0'
      and result->>'entity_lineage_drift' = '0'
      and result->>'missing_source_locations' = '0'
      and result->>'source_location_drift' = '0'
      and result->>'source_location_coordinate_drift' = '0'
      and result->>'decision_source_id_set_drift' = '0'
      and result->>'decision_source_owner_drift' = '0'
  ) as manual_location_reconciliation_dry_run
from checks;
